// ServerInterface represents all server handlers.
type ServerInterface interface {
	// RecordRestoreTest Record a backup restore test (operator, interim only, FR-015)
	// (POST /backups/restore-tests)
	RecordRestoreTest(w http.ResponseWriter, r *http.Request, params RecordRestoreTestParams)
	// ListCells Cells (owner, operator)
	// (GET /cells)
	ListCells(w http.ResponseWriter, r *http.Request)
	// GetCellCapacity Users placed against capacity, per host
	// (GET /cells/{cellId}/capacity)
	GetCellCapacity(w http.ResponseWriter, r *http.Request, cellId openapi_types.UUID)
	// MarkGatewayPairPTA Record PTA registration of a pair's egress IP (owner, FR-011)
	// (POST /gateway-pairs/{name}:pta)
	MarkGatewayPairPTA(w http.ResponseWriter, r *http.Request, name string)
	// GetInterim Interim hosting limits and usage (FR-010 to FR-012)
	// (GET /interim)
	GetInterim(w http.ResponseWriter, r *http.Request)
	// RecordPayment Record a manual payment with reference and optional proof (owner, FR-016c)
	// (POST /invoices/{invoiceId}/payments)
	RecordPayment(w http.ResponseWriter, r *http.Request, invoiceId InvoiceId, params RecordPaymentParams)
	// IssueInvoice Issue a draft invoice. Assigns the number; the invoice becomes immutable.
	// (POST /invoices/{invoiceId}:issue)
	IssueInvoice(w http.ResponseWriter, r *http.Request, invoiceId InvoiceId, params IssueInvoiceParams)
	// ListPlans Plans with their versions (owner)
	// (GET /plans)
	ListPlans(w http.ResponseWriter, r *http.Request)
	// CreatePlan Create a plan (owner)
	// (POST /plans)
	CreatePlan(w http.ResponseWriter, r *http.Request, params CreatePlanParams)
	// DraftPlanVersion Draft a new plan version (owner)
	// (POST /plans/{planId}/versions)
	DraftPlanVersion(w http.ResponseWriter, r *http.Request, planId PlanId, params DraftPlanVersionParams)
	// PublishPlanVersion Publish a draft version. The previous published version becomes superseded.
	// (POST /plans/{planId}/versions/{version}:publish)
	PublishPlanVersion(w http.ResponseWriter, r *http.Request, planId PlanId, version int, params PublishPlanVersionParams)
	// ProviderWebhook Payment provider webhook. Signature-verified, stored idempotently. 404 for manual.
	// (POST /providers/{provider}/webhooks)
	ProviderWebhook(w http.ResponseWriter, r *http.Request, provider string)
	// ListTenants List tenants (owner, operator)
	// (GET /tenants)
	ListTenants(w http.ResponseWriter, r *http.Request, params ListTenantsParams)
	// CreateTenant Create or update a tenant from a tenant definition (owner). Idempotent.
	// (POST /tenants)
	CreateTenant(w http.ResponseWriter, r *http.Request, params CreateTenantParams)
	// GetTenant Get a tenant with stack status and management URL
	// (GET /tenants/{tenantId})
	GetTenant(w http.ResponseWriter, r *http.Request, tenantId TenantId)
	// ListAudit Audit records for the tenant (FR-026)
	// (GET /tenants/{tenantId}/audit)
	ListAudit(w http.ResponseWriter, r *http.Request, tenantId TenantId, params ListAuditParams)
	// ListGroups List groups
	// (GET /tenants/{tenantId}/groups)
	ListGroups(w http.ResponseWriter, r *http.Request, tenantId TenantId)
	// CreateGroup Create a group
	// (POST /tenants/{tenantId}/groups)
	CreateGroup(w http.ResponseWriter, r *http.Request, tenantId TenantId, params CreateGroupParams)
	// DeleteGroup Delete a group
	// (DELETE /tenants/{tenantId}/groups/{groupId})
	DeleteGroup(w http.ResponseWriter, r *http.Request, tenantId TenantId, groupId openapi_types.UUID)
	// PatchGroup Rename a group or change members
	// (PATCH /tenants/{tenantId}/groups/{groupId})
	PatchGroup(w http.ResponseWriter, r *http.Request, tenantId TenantId, groupId openapi_types.UUID, params PatchGroupParams)
	// GetIdentity Get sign-in settings
	// (GET /tenants/{tenantId}/identity)
	GetIdentity(w http.ResponseWriter, r *http.Request, tenantId TenantId)
	// PutIdentity Set sign-in methods, upstream IdPs, allowed domains and MFA (FR-002, FR-003, FR-013)
	// (PUT /tenants/{tenantId}/identity)
	PutIdentity(w http.ResponseWriter, r *http.Request, tenantId TenantId, params PutIdentityParams)
	// ListInvoices Invoices for the tenant
	// (GET /tenants/{tenantId}/invoices)
	ListInvoices(w http.ResponseWriter, r *http.Request, tenantId TenantId)
	// DraftInvoice Draft an invoice for a subscription period (owner)
	// (POST /tenants/{tenantId}/invoices)
	DraftInvoice(w http.ResponseWriter, r *http.Request, tenantId TenantId, params DraftInvoiceParams)
	// ListIsolationTests Isolation test history, newest first (interim only)
	// (GET /tenants/{tenantId}/isolation-tests)
	ListIsolationTests(w http.ResponseWriter, r *http.Request, tenantId TenantId)
	// RecordIsolationTest Record an isolation test result (operator, interim only, FR-009)
	// (POST /tenants/{tenantId}/isolation-tests)
	RecordIsolationTest(w http.ResponseWriter, r *http.Request, tenantId TenantId, params RecordIsolationTestParams)
	// GetPostureRules Posture rules (FR-018)
	// (GET /tenants/{tenantId}/posture-rules)
	GetPostureRules(w http.ResponseWriter, r *http.Request, tenantId TenantId)
	// PutPostureRules Replace posture rules. Needs the posture_checks entitlement.
	// (PUT /tenants/{tenantId}/posture-rules)
	PutPostureRules(w http.ResponseWriter, r *http.Request, tenantId TenantId, params PutPostureRulesParams)
	// GetRoutingRules Rules at tenant, group and user level, each user's effective rule and conflicts (FR-005)
	// (GET /tenants/{tenantId}/routing-rules)
	GetRoutingRules(w http.ResponseWriter, r *http.Request, tenantId TenantId)
	// PutRoutingRules Replace routing rules. Empty destination lists are rejected (422).
	// (PUT /tenants/{tenantId}/routing-rules)
	PutRoutingRules(w http.ResponseWriter, r *http.Request, tenantId TenantId, params PutRoutingRulesParams)
	// ReconcileStack Force a reconcile run (operator)
	// (POST /tenants/{tenantId}/stack:reconcile)
	ReconcileStack(w http.ResponseWriter, r *http.Request, tenantId TenantId)
	// ReportStack Deployer reports applied hash and component health (contracts/tenant-stack.md)
	// (POST /tenants/{tenantId}/stack:report)
	ReportStack(w http.ResponseWriter, r *http.Request, tenantId TenantId)
	// GetSubscription Current subscription
	// (GET /tenants/{tenantId}/subscription)
	GetSubscription(w http.ResponseWriter, r *http.Request, tenantId TenantId)
	// CreateSubscription Subscribe the tenant to a pinned plan version (owner, FR-016a)
	// (POST /tenants/{tenantId}/subscription)
	CreateSubscription(w http.ResponseWriter, r *http.Request, tenantId TenantId, params CreateSubscriptionParams)
	// GetSubscriptionHistory Subscription events
	// (GET /tenants/{tenantId}/subscription/history)
	GetSubscriptionHistory(w http.ResponseWriter, r *http.Request, tenantId TenantId)
	// ChangeSubscription Change quantity or migrate plan version, with a reason (owner, FR-016b)
	// (POST /tenants/{tenantId}/subscription:change)
	ChangeSubscription(w http.ResponseWriter, r *http.Request, tenantId TenantId, params ChangeSubscriptionParams)
	// GetUsage Per-user connection status, last seen and bytes; never-installed and inactive lists
	// (GET /tenants/{tenantId}/usage)
	GetUsage(w http.ResponseWriter, r *http.Request, tenantId TenantId, params GetUsageParams)
	// ListUsers Users with status, last seen, connected and device count
	// (GET /tenants/{tenantId}/users)
	ListUsers(w http.ResponseWriter, r *http.Request, tenantId TenantId, params ListUsersParams)
	// DeleteUser Remove a user and free the seat
	// (DELETE /tenants/{tenantId}/users/{userId})
	DeleteUser(w http.ResponseWriter, r *http.Request, tenantId TenantId, userId UserId)
	// PatchUser Disable, enable, change role or groups
	// (PATCH /tenants/{tenantId}/users/{userId})
	PatchUser(w http.ResponseWriter, r *http.Request, tenantId TenantId, userId UserId, params PatchUserParams)
	// ImportUsers Bulk import users and send invitations. Refused past the seat limit (FR-016).
	// (POST /tenants/{tenantId}/users:import)
	ImportUsers(w http.ResponseWriter, r *http.Request, tenantId TenantId, params ImportUsersParams)
	// ResumeTenant Resume a suspended tenant (owner)
	// (POST /tenants/{tenantId}:resume)
	ResumeTenant(w http.ResponseWriter, r *http.Request, tenantId TenantId, params ResumeTenantParams)
	// SuspendTenant Suspend a tenant (owner). Disables users, keeps data.
	// (POST /tenants/{tenantId}:suspend)
	SuspendTenant(w http.ResponseWriter, r *http.Request, tenantId TenantId, params SuspendTenantParams)
}

// Unimplemented server implementation that returns http.StatusNotImplemented for each endpoint.

type Unimplemented struct{}

