func (e *UnescapedCookieParamError) Unwrap() error {
	return e.Err
}

type UnmarshalingParamError struct {
	ParamName string
	Err       error
}

func (e *UnmarshalingParamError) Error() string {
	return fmt.Sprintf("Error unmarshaling parameter %s as JSON: %s", e.ParamName, e.Err.Error())
}

func (e *UnmarshalingParamError) Unwrap() error {
	return e.Err
}

type RequiredParamError struct {
	ParamName string
}

func (e *RequiredParamError) Error() string {
	return fmt.Sprintf("Query argument %s is required, but not found", e.ParamName)
}

type RequiredHeaderError struct {
	ParamName string
	Err       error
}

func (e *RequiredHeaderError) Error() string {
	return fmt.Sprintf("Header parameter %s is required, but not found", e.ParamName)
}

func (e *RequiredHeaderError) Unwrap() error {
	return e.Err
}

type InvalidParamFormatError struct {
	ParamName string
	Err       error
}

func (e *InvalidParamFormatError) Error() string {
	return fmt.Sprintf("Invalid format for parameter %s: %s", e.ParamName, e.Err.Error())
}

func (e *InvalidParamFormatError) Unwrap() error {
	return e.Err
}

type TooManyValuesForParamError struct {
	ParamName string
	Count     int
}

func (e *TooManyValuesForParamError) Error() string {
	return fmt.Sprintf("Expected one value for %s, got %d", e.ParamName, e.Count)
}

// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tenants", wrapper.ListTenants)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/tenants", wrapper.CreateTenant)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tenants/{tenantId}", wrapper.GetTenant)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/tenants/{tenantId}:suspend", wrapper.SuspendTenant)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/tenants/{tenantId}:resume", wrapper.ResumeTenant)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tenants/{tenantId}/identity", wrapper.GetIdentity)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/tenants/{tenantId}/identity", wrapper.PutIdentity)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tenants/{tenantId}/users", wrapper.ListUsers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/tenants/{tenantId}/users:import", wrapper.ImportUsers)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/tenants/{tenantId}/users/{userId}", wrapper.DeleteUser)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/tenants/{tenantId}/users/{userId}", wrapper.PatchUser)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tenants/{tenantId}/groups", wrapper.ListGroups)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/tenants/{tenantId}/groups", wrapper.CreateGroup)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/tenants/{tenantId}/groups/{groupId}", wrapper.DeleteGroup)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/tenants/{tenantId}/groups/{groupId}", wrapper.PatchGroup)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tenants/{tenantId}/routing-rules", wrapper.GetRoutingRules)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/tenants/{tenantId}/routing-rules", wrapper.PutRoutingRules)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tenants/{tenantId}/posture-rules", wrapper.GetPostureRules)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/tenants/{tenantId}/posture-rules", wrapper.PutPostureRules)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tenants/{tenantId}/usage", wrapper.GetUsage)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tenants/{tenantId}/audit", wrapper.ListAudit)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tenants/{tenantId}/subscription", wrapper.GetSubscription)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/tenants/{tenantId}/subscription", wrapper.CreateSubscription)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/tenants/{tenantId}/subscription:change", wrapper.ChangeSubscription)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tenants/{tenantId}/subscription/history", wrapper.GetSubscriptionHistory)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tenants/{tenantId}/invoices", wrapper.ListInvoices)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/tenants/{tenantId}/invoices", wrapper.DraftInvoice)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/invoices/{invoiceId}:issue", wrapper.IssueInvoice)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/invoices/{invoiceId}/payments", wrapper.RecordPayment)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/plans", wrapper.ListPlans)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/plans", wrapper.CreatePlan)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/plans/{planId}/versions", wrapper.DraftPlanVersion)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/plans/{planId}/versions/{version}:publish", wrapper.PublishPlanVersion)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/providers/{provider}/webhooks", wrapper.ProviderWebhook)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/cells", wrapper.ListCells)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/cells/{cellId}/capacity", wrapper.GetCellCapacity)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/gateway-pairs/{name}:pta", wrapper.MarkGatewayPairPTA)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/tenants/{tenantId}/stack:reconcile", wrapper.ReconcileStack)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/tenants/{tenantId}/stack:report", wrapper.ReportStack)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/tenants/{tenantId}/isolation-tests", wrapper.ListIsolationTests)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/tenants/{tenantId}/isolation-tests", wrapper.RecordIsolationTest)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/backups/restore-tests", wrapper.RecordRestoreTest)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/interim", wrapper.GetInterim)
	})

	return r
}

